import type { BibleVersionMeta } from '../types/bible';

/** Raw shape of the bundled data (`.json` for the inline versions, `.bible` for the asset ones). */
export type RawBook = { abbrev: string; name: string; chapters: string[][] };

export interface BibleVersionEntry extends BibleVersionMeta {
  /**
   * Inline version: lazy loader. Metro needs literal `require()` paths to bundle the files, and
   * wrapping them in a function avoids parsing ~4 MB per version at app start.
   */
  load?: () => RawBook[];
  /**
   * Asset version: Metro asset id of the `.bible` file (generated by `scripts/build-bible-versions.mjs`).
   * It is not part of the JS bundle; `ensureVersionLoaded` reads and parses it on demand.
   * To add a version: add the source folder to that script, run it, and add one entry here.
   */
  asset?: number;
}

